(()=>{function render(){let state;try{state=Starboard.load(localStorage)}catch{document.querySelector('#notice').textContent='無法讀取進度，請確認瀏覽器儲存設定後重新整理。';document.querySelector('#stages').replaceChildren();return}document.querySelector('#progress').textContent=`已通關 ${state.firstClears.length} / 20 · 星輝碎片 ${state.shards}`;const list=document.querySelector('#stages');list.replaceChildren();for(const stage of ChapterOne.stages){const cleared=state.firstClears.includes(stage.id),open=ChapterOne.unlocked(stage.id,state.firstClears),card=document.createElement('article');card.className='stage';card.innerHTML=`<h2>1-${stage.id} ${stage.name}</h2><div class="portraits">${stage.monsters.map(id=>{const m=MonsterData.byId[id];return `<img src="${m.image}" alt="${m.name}" title="${m.name}">`}).join('')}</div><p>${stage.monsters.map(id=>MonsterData.byId[id].name).join('、')}</p><p>${cleared?'已領首通獎勵 · 重打無獎勵':'首通 '+Starboard.firstClearReward(stage.id)+' 星輝碎片'}</p>${open?`<a href="portrait.html?stage=${stage.id}">${cleared?'再次挑戰':'挑戰關卡'}</a>`:'<p>完成前一關後解鎖</p>'}`;list.append(card)}}render();window.addEventListener('pageshow',render);window.addEventListener('storage',render)})();
